'use client';

import { useEffect } from 'react';
import { getCalApi } from '@calcom/atoms';

interface CalBookingWidgetProps {
  calLink: string; // e.g. 'your-username/30min'
  onBookingSuccess?: (data: { uid: string }) => void;
}

export function CalBookingWidget({
  calLink,
  onBookingSuccess,
}: CalBookingWidgetProps): JSX.Element {
  useEffect(() => {
    (async function initCal() {
      const cal = await getCalApi({
        namespace: 'booking-widget',
      });

      cal('ui', {
        styles: { branding: { brandColor: '#000000' } },
        hideEventTypeDetails: false,
        layout: 'month_view',
      });

      if (onBookingSuccess) {
        cal('on', {
          action: 'bookingSuccessful',
          callback: (e: CustomEvent) => {
            const { uid } = e.detail.data as { uid: string };
            onBookingSuccess({ uid });
          },
        });
      }
    })();
  }, [onBookingSuccess]);

  return (
    <div
      data-cal-namespace="booking-widget"
      data-cal-link={calLink}
      data-cal-config='{"layout":"month_view"}'
      style={{
        width: '100%',
        height: '700px',
        overflow: 'scroll',
      }}
    />
  );
}

// Usage:
// <CalBookingWidget
//   calLink="jane/30min"
//   onBookingSuccess={({ uid }) => console.log('Booked:', uid)}
// />

const CAL_API_BASE = 'https://api.cal.com/v2';
const CAL_API_VERSION = '2024-08-13';

interface CalBooking {
  id: number;
  uid: string;
  title: string;
  status: 'accepted' | 'pending' | 'cancelled' | 'rejected';
  startTime: string;
  endTime: string;
  attendees: Array<{
    name: string;
    email: string;
    timeZone: string;
  }>;
  eventType: {
    id: number;
    title: string;
    slug: string;
  };
}

interface CalBookingsResponse {
  status: string;
  data: CalBooking[];
  error?: { message: string };
}

async function listBookings(options?: {
  status?: 'upcoming' | 'past' | 'cancelled';
  take?: number;
  skip?: number;
}): Promise<CalBooking[]> {
  const params = new URLSearchParams();
  if (options?.status) params.set('status', options.status);
  if (options?.take) params.set('take', String(options.take));
  if (options?.skip) params.set('skip', String(options.skip));

  const url = `${CAL_API_BASE}/bookings${params.size > 0 ? `?${params}` : ''}`;

  const response = await fetch(url, {
    headers: {
      Authorization: `Bearer ${process.env.CAL_API_KEY}`,
      'cal-api-version': CAL_API_VERSION,
    },
  });

  if (!response.ok) {
    const error = await response.json() as CalBookingsResponse;
    throw new Error(`Cal.com API error: ${error.error?.message ?? response.statusText}`);
  }

  const result = await response.json() as CalBookingsResponse;
  return result.data;
}

// Example: fetch upcoming bookings
const upcomingBookings = await listBookings({ status: 'upcoming', take: 20 });

for (const booking of upcomingBookings) {
  console.log(`[${booking.status.toUpperCase()}] ${booking.title}`);
  console.log(`  Start: ${new Date(booking.startTime).toLocaleString()}`);
  console.log(`  End:   ${new Date(booking.endTime).toLocaleString()}`);
  for (const attendee of booking.attendees) {
    console.log(`  Attendee: ${attendee.name} <${attendee.email}>`);
  }
}
